// Vicero signs every call: hex HMAC-SHA256 over "<timestamp>." + the raw body, using
// N8N_WEBHOOK_SIGNING_SECRET (apps/api/app/integrations/n8n_client.py sign()/verify_callback()).
// Fails CLOSED: no secret configured, missing headers, stale timestamp or bad MAC => rejected.
const crypto = require('crypto');
const item = $input.first();
const reject = (reason) => [{ json: { verified: false, reason } }];
const secret = $env['N8N_WEBHOOK_SIGNING_SECRET'] || '';
if (!secret) return reject('signing secret is not configured on this n8n');
const h = item.json.headers || {};
const sig = String(h['x-vicero-signature'] || '');
const ts = String(h['x-vicero-timestamp'] || '');
if (!sig || !ts) return reject('missing signature headers');
if (!/^\d{1,12}$/.test(ts) || Math.abs(Date.now() / 1000 - Number(ts)) > 300) return reject('stale or malformed timestamp');
if (!item.binary || !item.binary.data) return reject('raw body unavailable (Webhook option rawBody must be on)');
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest('hex');
const a = Buffer.from(expected, 'utf8');
const b = Buffer.from(sig, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject('bad signature');
return [{ json: { ...item.json, verified: true } }];

// DEMO FIXTURE - every name, id, price, doctor, slot and order in this workflow is fictional demo data.
// State (bookings, counters) lives in n8n workflow static data and is NOT part of this export.
const body = $input.first().json.body || {};
const a = body.args || {};
const S = $getWorkflowStaticData('global');
S.bookings = S.bookings || {};
S.counter = S.counter || 0;
const need = (fields) => fields.filter((f) => a[f] === undefined || a[f] === null || String(a[f]).trim() === '');
const bad = (error, extra = {}) => [{ json: { ok: false, error, ...extra } }];
const nextId = (prefix) => { S.counter += 1; return prefix + '-' + String(1000 + S.counter); };
const isDate = (s) => /^\d{4}-\d{2}-\d{2}$/.test(String(s));
const isTime = (s) => /^([01]\d|2[0-3]):[0-5]\d$/.test(String(s));

const OPEN = 11, CLOSE = 22, SEATS = 40, MAX_PARTY = 12;
const used = (date, time) => Object.values(S.bookings).filter((b) => b.status === 'confirmed' && b.date === date && b.time === time).reduce((n, b) => n + b.party_size, 0);
const slotsFor = (date, size) => { const out = []; for (let h = OPEN; h < CLOSE; h++) { const t = String(h).padStart(2, '0') + ':00'; if (SEATS - used(date, t) >= size) out.push(t); } return out; };
switch (a.action) {
  case 'check_availability': {
    const m = need(['date', 'time', 'party_size']); if (m.length) return bad('missing fields: ' + m.join(', '));
    if (!isDate(a.date) || !isTime(a.time)) return bad('date must be YYYY-MM-DD and time HH:MM (24h)');
    const size = Number(a.party_size); if (!(size >= 1 && size <= MAX_PARTY)) return bad('party_size must be 1-' + MAX_PARTY + ' (larger groups: call the restaurant)');
    const h = Number(a.time.slice(0, 2)); if (h < OPEN || h >= CLOSE) return bad('closed at that time', { hours: '11:00-22:00 daily', available_times: slotsFor(a.date, size) });
    const left = SEATS - used(a.date, a.time);
    return [{ json: { ok: true, available: left >= size, seats_left: left, available_times: slotsFor(a.date, size) } }];
  }
  case 'book_table': {
    const m = need(['name', 'phone', 'date', 'time', 'party_size']); if (m.length) return bad('missing fields: ' + m.join(', '));
    if (!isDate(a.date) || !isTime(a.time)) return bad('date must be YYYY-MM-DD and time HH:MM (24h)');
    const size = Number(a.party_size); if (!(size >= 1 && size <= MAX_PARTY)) return bad('party_size must be 1-' + MAX_PARTY);
    const h = Number(a.time.slice(0, 2)); if (h < OPEN || h >= CLOSE) return bad('closed at that time', { hours: '11:00-22:00 daily' });
    if (SEATS - used(a.date, a.time) < size) return bad('no availability at that time', { available_times: slotsFor(a.date, size) });
    const id = nextId('HTB');
    S.bookings[id] = { id, name: a.name, phone: a.phone, date: a.date, time: a.time, party_size: size, notes: a.notes || null, status: 'confirmed' };
    return [{ json: { ok: true, confirmation_id: id, name: a.name, date: a.date, time: a.time, party_size: size, status: 'confirmed', message: 'Table held for 15 minutes past the booking time.' } }];
  }
  case 'lookup_booking': {
    const b = S.bookings[a.confirmation_id]; if (!b) return bad('no booking found for that confirmation id');
    return [{ json: { ok: true, ...b } }];
  }
  case 'cancel_booking': {
    const b = S.bookings[a.confirmation_id]; if (!b) return bad('no booking found for that confirmation id');
    b.status = 'cancelled';
    return [{ json: { ok: true, confirmation_id: b.id, status: 'cancelled' } }];
  }
  default: return bad('unknown action', { valid_actions: ['check_availability', 'book_table', 'lookup_booking', 'cancel_booking'] });
}
